{"path": "middleware.ts", "content": "import { NextResponse, type NextRequest } from 'next/server'

/**
 * Next.js middleware.
 *
 * - Generates a unique request id for every request and attaches it to the
 *   response via the `X-Request-Id` header.
 * - Logs the request pathname to the console.
 */
export function middleware(request: NextRequest) {
  const requestId =
    request.headers.get('x-request-id') ?? crypto.randomUUID()

  console.log(`[middleware] ${request.method} ${request.nextUrl.pathname}`)

  const response = NextResponse.next({
    request: {
      headers: request.headers,
    },
  })

  response.headers.set('X-Request-Id', requestId)

  return response
}

export const config = {
  // Run on every route, including the root, while skipping Next.js internals.
  matcher: ['/((?!_next/static|_next/images|favicon.ico).*)'],
}
"}

